import React, { useState } from 'react';
import './Ahorro.css'; // Asegúrate de tener estilos para la tabla

const Ahorro = () => {
    const [salary, setSalary] = useState(0);
    const [monthlyExpenses, setMonthlyExpenses] = useState(0);
    const [amountToSave, setAmountToSave] = useState(0);
    const [weeklySavings, setWeeklySavings] = useState(0);

    const handleCalculate = () => {
        const savings = salary - monthlyExpenses;
        setAmountToSave(savings);
        setWeeklySavings(savings / 4); // Asumiendo 4 semanas en un mes
    };

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            
            <div className="input-section">
                <label>
                    Salario Mensual:
                    <input
                        type="number"
                        value={salary}
                        onChange={(e) => setSalary(parseFloat(e.target.value))}
                        placeholder="Ingresa tu salario"
                    />
                </label>
                <label>
                    Gastos Mensuales:
                    <input
                        type="number"
                        value={monthlyExpenses}
                        onChange={(e) => setMonthlyExpenses(parseFloat(e.target.value))}
                        placeholder="Ingresa tus gastos mensuales"
                    />
                </label>
                <button onClick={handleCalculate}>Calcular Ahorro</button>
            </div>

            <div className="ahorro-content">
                <h2>Resumen de Ahorro</h2>
                <table className="ahorro-table">
                    <thead>
                        <tr>
                            <th>Salario Mensual</th>
                            <th>Gastos Mensuales</th>
                            <th>Cantidad para Ahorrar</th>
                            <th>Ahorro Semanal</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>${salary.toFixed(2)}</td>
                            <td>${monthlyExpenses.toFixed(2)}</td>
                            <td>${amountToSave.toFixed(2)}</td>
                            <td>${weeklySavings.toFixed(2)}</td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default Ahorro;
